// @EXPECTED exit:0
// @EXPECTED out:len=600
#include <stdio.h>
/* 回归: 字符串字面量 512->2048 扩容 (STRBUF_SZ) - 600字节不截断 */
int main(void) {
    char *s = "";
    int n = 0;
    while (s[n] != 0) n++;
    printf("len=%d\n", n);
    if (n != 600) return 1;
    /* 抽样检查首中尾字符 */
    if (s[0] != 'A' || s[599] != 'A' || s[300] != 'A') return 2;
    return 0;
}
